<script setup>
import {previewMode} from '../preview/mode'

import {ref,onMounted,computed} from 'vue'
import Icon from '../Icon.vue'
import {isDemo} from '../service'
import {walletCall,localExport} from './walletClient'
const props=defineProps({member:Object}),emit=defineEmits(['notify'])
const owner=computed(()=>props.member.role==='PlatformAdmin'),data=ref(null),region=ref('Local'),error=ref(''),busy=ref(false),showMethod=ref(false),amount=ref(''),method=ref(''),reason=ref(''),reference=ref(''),receipt=ref(''),details=ref(null),page=ref(0)
const form=ref({kind:'Local Bank',bank:'',branch:'',holder:'',account:'',email:'',payoneer_id:'',swift:'',iban:''})
const fields=computed(()=>({'Local Bank':{bank:'Bank name',branch:'Branch',holder:'Account holder name',account:'Account number'},Wise:{email:'Wise email'},Payoneer:{payoneer_id:'Payoneer ID'},'SWIFT / IBAN':{bank:'Bank name',holder:'Account holder name',swift:'SWIFT / BIC',iban:'IBAN'}}[form.value.kind]))
const money=(minor,currency=data.value?.wallet?.currency||'LKR')=>new Intl.NumberFormat('en',{style:'currency',currency}).format(minor/100)
async function load(){error.value='';try{data.value=await walletCall(owner.value?'admin_queue':'dashboard',owner.value?{region:region.value,page:page.value}:{page:page.value},props.member);if(data.value.wallet?.country!=='Sri Lanka')form.value.kind='Wise'}catch(e){error.value=e.message}}
async function action(name,args){busy.value=true;error.value='';try{await walletCall(name,args,props.member);await load();emit('notify',isDemo?'Preview updated. No money was transferred.':'Wallet record updated.')}catch(e){error.value=e.message}finally{busy.value=false}}
async function submitMethod(){await action('submit_method',{wallet:data.value.wallet.name,data:{...form.value,country:data.value.wallet.country}});if(!error.value)showMethod.value=false}
let payoutIntent=null
async function request(){
  const signature=JSON.stringify([data.value.wallet.name,method.value,amount.value])
  if(!payoutIntent||payoutIntent.signature!==signature)payoutIntent={signature,key:crypto.randomUUID()}
  await action('request_payout',{wallet:data.value.wallet.name,method:method.value,amount:amount.value,request_key:payoutIntent.key})
  if(!error.value){payoutIntent=null;amount.value=''}
}
async function reveal(m){try{details.value=await walletCall('reveal_method',{method:m.name},props.member)}catch(e){error.value=e.message}}
async function exportCsv(){const rows=data.value.requests.filter(r=>r.status==='Processing'&&r.currency==='LKR');if(!rows.length){error.value='Move a local payout to Processing before export.';return}if(!isDemo){if(previewMode){error.value='Exports require the connected server.';return}const res=await fetch('/api/method/institute_lms.wallet.export_local',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Frappe-CSRF-Token':window.csrf_token||document.querySelector('meta[name=csrf-token]')?.content||''},body:JSON.stringify({requests:rows.map(r=>r.name)})});if(!res.ok){error.value='Export could not be generated';return}download(await res.blob())}else download(new Blob([localExport(rows)],{type:'text/csv'}))}
function download(blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sisu-local-payout-review.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(load)
</script>
<template><section class="wallet-page"><div class="page-heading"><div><span class="eyebrow">YOUR WORK. CLEARLY ACCOUNTED FOR.</span><h1>{{owner?'Payout desk.':'Your earnings, together.'}}</h1><p>{{owner?'Review methods and settle local or international payouts.':'A calm, clear view of what you have earned.'}}</p></div><span class="badge violet">{{isDemo?'Fictional funds · no transfers':'Earnings ledger'}}</span></div><p v-if="error" role="alert" class="error">{{error}}</p>
<template v-if="data&&!owner&&data.wallet"><div class="wallet-metrics"><article class="wallet-feature"><Icon name="Wallet"/><small>Available for payout</small><strong>{{money(data.wallet.available_minor)}}</strong><span>{{data.wallet.beneficiary==='Institute'?'Institute-owned class revenue':'Independent teaching revenue'}}</span></article><article class="panel"><Icon name="Clock3"/><small>Reserved for payouts</small><strong>{{money(data.wallet.held_minor)}}</strong><p>Held safely while finance processes your request.</p></article><article class="panel"><Icon name="ShieldCheck"/><small>Minimum payout</small><strong>{{money(data.minimum_minor)}}</strong><p>{{isDemo?'US$20 minimum · LKR uses an illustrative 300/USD demo rate':'Set by platform finance'}}.</p></article></div><p class="wallet-routing">Institute classes settle to the institute. Independent classes settle to the teacher. Each wallet keeps its own currency; balances are never added across currencies.</p><div class="wallet-columns"><section class="panel"><div class="section-heading"><h2>Payout destination</h2><button class="text-button" @click="showMethod=!showMethod">Add / update details</button></div><article v-for="m in data.methods" class="wallet-row"><div><strong>{{m.masked_label}}</strong><small>{{m.review_reason}}</small></div><span class="badge" :class="m.status==='Approved'?'green':'peach'">{{m.status}}</span></article><p v-if="!data.methods.length">Choose where your earnings should arrive.</p><form v-if="showMethod" @submit.prevent="submitMethod"><p v-if="isDemo" class="field-help">Use fictional details in this browser preview. Do not enter your real bank account.</p><label>Payment method<select v-model="form.kind"><option v-for="kind in data.wallet.country==='Sri Lanka'?['Local Bank']:['Wise','Payoneer','SWIFT / IBAN']">{{kind}}</option></select></label><label v-for="(label,key) in fields">{{label}}<input v-model="form[key]" :type="key==='email'?'email':'text'" required maxlength="140" autocomplete="off"></label><p class="field-help">Changes create a new revision for approval. An existing payout keeps its original approved destination.</p><button class="button primary" :disabled="busy">Submit for approval</button></form></section><section class="panel"><h2>Request a payout</h2><form @submit.prevent="request"><label>Approved destination<select v-model="method" required><option disabled value="">Select an approved method</option><option v-for="m in data.methods.filter(m=>m.status==='Approved')" :value="m.name">{{m.masked_label}}</option></select></label><label>Amount · {{data.wallet.currency}}<input v-model="amount" type="number" step="0.01" :min="data.minimum_minor/100" :max="data.wallet.available_minor/100" required></label><p class="field-help">This amount moves from available to reserved until completion or rejection.</p><button class="button primary" :disabled="busy||!data.methods.some(m=>m.status==='Approved')">Request payout <Icon name="ArrowUpRight" :size="16"/></button></form></section></div><section class="panel wallet-history"><h2>Your payout requests</h2><article v-for="r in data.requests" class="wallet-row"><strong>{{r.name}}</strong><span>{{money(r.amount_minor,r.currency)}}</span><span class="badge violet">{{r.status}}</span><small>{{r.transaction_reference||r.reason}}</small></article><p v-if="!data.requests.length">Your first request will appear here.</p><h2>Wallet activity</h2><article v-for="l in data.ledger" class="wallet-row"><span>{{l.kind}}<small>{{new Date(l.creation).toLocaleString()}}</small></span><strong>{{money(l.available_delta)}}</strong><small>{{l.reference}}</small></article><p v-if="!data.ledger.length">The opening preview balance is fictional. New requests create ledger entries below.</p><button v-if="!isDemo&&data.ledger.length===25" class="text-button" @click="page++;load()">Older activity</button></section></template>
<template v-else-if="data&&owner"><div class="tabs"><button v-for="r in ['Local','International']" :class="{selected:region===r}" @click="region=r;page=0;load()">{{r==='Local'?'Sri Lanka · local':'International'}}</button></div><section class="panel wallet-history"><h2>Payment details awaiting approval</h2><article v-for="m in data.methods" class="wallet-row"><div><strong>{{m.masked_label}}</strong><small>{{m.wallet}}</small></div><button class="button subtle small" @click="reveal(m)">Review details</button><button class="button primary small" :disabled="busy||!reason.trim()" @click="action('review_method',{method:m.name,decision:'Approved',reason})">Approve</button><button class="button subtle small" :disabled="busy||!reason.trim()" @click="action('review_method',{method:m.name,decision:'Rejected',reason})">Reject</button></article><p v-if="!data.methods.length">No payment methods waiting for review.</p><div v-if="details" class="wallet-sensitive"><strong>Finance review · sensitive details</strong><dl><template v-for="(v,k) in details"><dt>{{k}}</dt><dd>{{v}}</dd></template></dl><button class="text-button" @click="details=null">Hide details</button></div><label>Review / rejection reason<textarea v-model="reason" maxlength="1000" placeholder="Record the verification or rejection reason"></textarea></label></section><section class="panel wallet-history"><div class="section-heading"><h2>Payout queue</h2><button v-if="region==='Local'" class="button subtle" @click="exportCsv">Export CSV for bank review</button></div><label>Transfer reference<input v-model="reference" maxlength="140" placeholder="Bank or payment-service reference"></label><label v-if="!isDemo">Private receipt File ID (optional)<input v-model="receipt" placeholder="Attach the receipt to this payout first"></label><article v-for="r in data.requests" class="wallet-row"><div><strong>{{r.name}} · {{money(r.amount_minor,r.currency)}}</strong><small>{{r.wallet}} · {{r.status}}</small></div><button v-if="r.status==='Pending'" class="button subtle small" :disabled="busy" @click="action('update_payout',{request:r.name,status:'Processing'})">Mark processing</button><button v-if="r.status==='Processing'" class="button primary small" :disabled="busy||!reference.trim()" @click="action('update_payout',{request:r.name,status:'Completed',reference,receipt:receipt||undefined})">Record completed transfer</button><button class="text-button" :disabled="busy||!reason.trim()" @click="action('update_payout',{request:r.name,status:'Rejected',reason})">Reject & release</button></article><p v-if="!data.requests.length">All clear. New requests will appear here.</p><p class="field-help">Export does not send money. The CSV is a review format; use your bank's approved CEFTS/SLIPS import template before uploading. Record completion only after a confirmed transfer.</p></section></template><p v-else-if="data">Your verified payout wallet has not been provisioned yet.</p></section></template>
<style>.wallet-metrics{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:20px}.wallet-metrics article{padding:30px;display:flex;flex-direction:column;gap:18px;border-radius:25px}.wallet-metrics strong{font-size:32px}.wallet-feature{background:linear-gradient(130deg,#8c6bd6,#b59ddd);color:white;box-shadow:0 16px 40px #8865bc20}.wallet-feature :is(small,strong,span){color:white!important}.wallet-feature span{font-size:12px}.wallet-metrics p,.wallet-routing{font-size:12px}.wallet-routing{margin:25px 0;line-height:1.9}.wallet-columns{display:grid;grid-template-columns:1fr 1fr;gap:22px}.wallet-columns>.panel,.wallet-history{padding:28px}.wallet-page label{display:flex;flex-direction:column;gap:10px;margin:20px 0;font-size:12px}.wallet-page :is(input,select,textarea){padding:13px;border:1px solid var(--student-border);background:var(--student-card);color:var(--student-ink);border-radius:12px;width:100%}.wallet-page form .button{margin-top:18px}.wallet-row{display:flex;align-items:center;gap:18px;flex-wrap:wrap;padding:20px 0;border-bottom:1px solid var(--student-border);font-size:12px}.wallet-row>div{flex:1}.wallet-row small{display:block;margin-top:8px}.wallet-history{margin-top:24px}.wallet-history>h2{margin:20px 0}.wallet-sensitive{padding:22px;background:var(--student-soft);border-radius:16px;overflow-wrap:anywhere}.wallet-sensitive dl{display:grid;grid-template-columns:auto 1fr;gap:15px;font-size:12px}@media(max-width:850px){.wallet-metrics,.wallet-columns{grid-template-columns:1fr}.wallet-metrics article{padding:25px}.wallet-history,.wallet-columns>.panel{padding:20px}}</style>
